/** Native launch form model selection, frozen retry input and theme material acceptance. */
async page => {
  const context = await page.context().browser().newContext(), test = await context.newPage(), errors = []
  const assert = (value, message) => { if (!value) throw new Error(message) }
  test.on('pageerror', error => errors.push(error.message))
  try {
    await test.goto('http://127.0.0.1:39088/')
    await test.setViewportSize({ width: 1280, height: 900 })
    await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
    const dialog = test.getByRole('dialog'), model = dialog.getByRole('button', { name: '选择模型', exact: true })
    await model.waitFor()
    await dialog.locator('.vc-search-launch-dataset .vc-select-trigger').click()
    await test.getByRole('menuitem').filter({ hasText: '测试训练' }).first().click()
    assert((await model.innerText()).includes('Fixture / Default'), 'The native catalog default must be selected initially')
    await model.click()
    await test.getByRole('menuitem', { name: 'Fixture / Alternate', exact: true }).click()
    const material = await dialog.evaluate(el => getComputedStyle(el, '::before').backgroundColor)
    assert(material.includes('0.92') || material.includes('0.9') || material.startsWith('rgb('), 'The launch dialog must use the more opaque dialog material')
    const brief = await dialog.getByRole('textbox').inputValue()
    assert(brief.includes('测试训练'), 'The task brief must retain the profile name')
    await dialog.screenshot({ path: '.playwright-mcp/search-launch-model-desktop.png', animations: 'disabled' })
    await test.setViewportSize({ width: 390, height: 844 })
    const fits = await dialog.evaluate(el => { const box=el.getBoundingClientRect();return box.left>=0&&box.right<=innerWidth&&box.top>=0&&box.bottom<=innerHeight&&el.scrollWidth<=el.clientWidth+1 })
    assert(fits, 'The model selector must fit the narrow launch dialog')
    await dialog.getByRole('button', { name: '开始找图', exact: true }).click()
    await test.waitForFunction(() => window.searchFixture.calls.length === 1)
    const submitted = await test.evaluate(() => window.searchFixture.calls[0])
    assert(submitted.conversationModel.provider === 'fixture' && submitted.conversationModel.model === 'alternate', 'The selected catalog route must reach the launch payload')
    assert(!!submitted.datasetId, 'The selected completed dataset must reach the same launch')
    assert(submitted.includeNegativeDatasets === true, 'Every new form must include all valid negative references by default')
    assert((await test.evaluate(() => window.searchFixture.opened)).length === 0, 'A reserved Session identity must not navigate before creation')
    await test.evaluate(() => window.searchFixture.sessionReady())
    await test.waitForFunction(() => window.searchFixture.opened.length === 1)
    assert(await dialog.count() === 0, 'The form must close as soon as its real Session exists, before model preparation finishes')
    await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
    await dialog.waitFor()
    assert(await dialog.getByRole('button', { name: '选择模型', exact: true }).isDisabled(), 'Admitted launch model choices must remain frozen on reopen')
    assert((await dialog.getByRole('button', { name: '选择模型', exact: true }).innerText()).includes('Alternate'), 'Reopening must retain the admitted model')
    await dialog.getByRole('button', { name: '关闭', exact: true }).last().click()
    await test.evaluate(() => window.searchFixture.accept())
    await test.getByRole('button', { name: '打开会话', exact: true }).click()
    assert((await test.evaluate(() => window.searchFixture.opened)).length === 2, 'Explicitly opening progress must reuse the same native Session')
    await test.evaluate(() => window.searchFixture.theme('light'))
    await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
    await dialog.waitFor()
    await dialog.screenshot({ path: '.playwright-mcp/search-launch-model-light-narrow.png', animations: 'disabled' })
    await test.keyboard.press('Escape')
    assert(await dialog.count() === 0, 'Escape must dismiss the launch form')
    await test.goto('http://127.0.0.1:39088/?empty')
    await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
    await dialog.getByText('2 个反例数据集 · 2 张反例图片（去重）', { exact: true }).waitFor()
    assert((await dialog.locator('.vc-search-launch-dataset').innerText()).includes('反例观察包会自动附带'), 'The missing complete package must explain why negative observation packages are supporting data')
    assert((await dialog.locator('.vc-search-launch-dataset .vc-select-trigger').innerText()).includes('自动使用当前完整包'), 'An empty current package list must retain automatic preparation')
    assert(await dialog.getByRole('button', { name: '开始找图', exact: true }).isEnabled(), 'Missing a completed current package must not block the automatic workflow')
    await test.setViewportSize({ width: 1280, height: 900 })
    await dialog.screenshot({ path: '.playwright-mcp/search-launch-auto-negative-datasets.png', animations: 'disabled' })
    await dialog.getByRole('button', { name: '开始找图', exact: true }).click()
    await test.waitForFunction(() => window.searchFixture.calls.length === 1)
    const automatic = await test.evaluate(() => window.searchFixture.calls[0])
    assert(automatic.autoPrepareDataset === true && automatic.includeNegativeDatasets === true && !automatic.datasetId, 'Automatic preparation and the negative policy must be frozen in the actual request')
    await test.evaluate(() => window.searchFixture.datasetPreparing())
    await test.waitForFunction(() => window.searchFixture.opened.length === 1)
    assert(await dialog.count() === 0, 'Dataset preparation must continue after navigating to the created Session')
    assert(errors.length === 0, 'The launch form must not throw browser errors')
    const result = { catalogDefault: true, selectedModelSubmitted: true, datasetSubmitted: true, defaultNegativeDatasets: true, automaticMissingPackage: true, navigateDuringDatasetPreparation: true, frozenOnReopen: true, dialogMaterial: true, narrowOverflow: false, nativeNavigation: true, navigateAfterSessionCreation: true, navigateBeforeModelReady: true, escapeCloses: true, themes: ['dark', 'light'], errors }
    const expected = await (await test.request.get('http://127.0.0.1:39088/search-launch-ui.expected.json')).json()
    assert(JSON.stringify(result) === JSON.stringify(expected), 'Search launch acceptance snapshot differs: ' + JSON.stringify(result))
    return result
  } finally { await context.close() }
}
